package digital.vmstudio.code.core.ai.antigravity

/**
 * Builds shell commands to interact with Google Antigravity CLI (`agy`) on remote laptops or servers.
 */
object AntigravityCommandBuilder {
    const val DEFAULT_BINARY = "agy"

    private const val DISCOVERY_SCRIPT_BASE64 =
        ""

    fun discoverSessionsCommand(): String {
        return "powershell -NoProfile -NonInteractive -EncodedCommand $DISCOVERY_SCRIPT_BASE64"
    }

    fun resumeCommand(
        conversationId: String,
        prompt: String,
        model: String? = null,
        binary: String = DEFAULT_BINARY,
    ): String {
        val parts = mutableListOf<String>()
        parts += binary
        parts += "--conversation"
        parts += shellQuote(conversationId)
        parts += "--dangerously-skip-permissions"
        if (!model.isNullOrBlank()) {
            parts += "--model"
            parts += shellQuote(model)
        }
        parts += "-p"
        parts += shellQuote(prompt)
        return parts.joinToString(" ")
    }

    fun continueLatestCommand(
        prompt: String,
        model: String? = null,
        binary: String = DEFAULT_BINARY,
    ): String {
        val parts = mutableListOf<String>()
        parts += binary
        parts += "--continue"
        parts += "--dangerously-skip-permissions"
        if (!model.isNullOrBlank()) {
            parts += "--model"
            parts += shellQuote(model)
        }
        parts += "-p"
        parts += shellQuote(prompt)
        return parts.joinToString(" ")
    }

    fun shellQuote(text: String): String {
        if (text.isEmpty()) return "''"
        return "'" + text.replace("'", "'\\''") + "'"
    }
}
